import { resolveSystemLogoSrc } from '@linm-soft-org/linm-web-common-components';

type ShellBrandingSnap = {
  assetQuery?: string;
};

/**
 * Same cache-bust as Navigation sidebar (`/icons/logo-128.png?v={Root version}`).
 * `resolveSystemLogoSrc` returns the path; Root `assetQuery` must be appended.
 */
export function resolveGuestSystemLogoSrc(): string {
  const src = resolveSystemLogoSrc();
  if (typeof window === 'undefined') return src;
  const q = (window as { __LINM_SHELL_BRANDING__?: ShellBrandingSnap })
    .__LINM_SHELL_BRANDING__?.assetQuery?.trim();
  if (!q || !src || src.startsWith('data:') || src.includes('?')) return src;
  if (!src.includes('/icons/')) return src;
  return `${src}${q.startsWith('?') ? q : `?${q}`}`;
}
