/**
 * API toast — SSOT web-app/rule/form-api-error-handling.md
 * Also reads RTK unwrap SerializedError (`{ message }` not instanceof Error).
 */

export const SYSTEM_ERROR_MESSAGE = 'Hệ thống lỗi vui lòng thử lại sau';

const GENERIC_HTTP_MARKERS = [
  'API request failed',
  'Internal Server Error',
  'Request failed',
  'Lỗi API',
];

function isApiConnectionError(err: unknown): err is Error & { kind: string } {
  return err instanceof Error && err.name === 'ApiConnectionError';
}

function readMessage(err: unknown): string {
  if (err instanceof Error) return err.message.trim();
  if (err && typeof err === 'object' && 'message' in err) {
    const raw = (err as { message?: unknown }).message;
    return typeof raw === 'string' ? raw.trim() : '';
  }
  return '';
}

export function getApiErrorMessage(
  err: unknown,
  _legacyFallback?: string,
  options?: { httpStatus?: number },
): string {
  if (isApiConnectionError(err)) return err.message;
  if (options?.httpStatus != null && options.httpStatus >= 500) {
    return SYSTEM_ERROR_MESSAGE;
  }
  const m = readMessage(err);
  if (!m) return SYSTEM_ERROR_MESSAGE;
  if (GENERIC_HTTP_MARKERS.some((x) => m === x || m.startsWith(x))) {
    return SYSTEM_ERROR_MESSAGE;
  }
  return m;
}
